// Real Human Face & Articulation Illustration Images for Chinese Pinyin Consonants

const MOUTH_IMAGES = {
  bilabial: "data:image/png;base64,",
  labiodental: "data:image/png;base64,",
  alveolar: "data:image/png;base64,",
  velar: "data:image/png;base64,",
  palatal: "data:image/png;base64,",
  dental: "data:image/png;base64,",
  retroflex: "data:image/png;base64,"
};

export function getMouthDiagramSVG(char) {
  const c = char ? char.toLowerCase() : '';

  let key = 'bilabial';
  let title = 'Âm hai môi (b, p, m): Hai môi khép dính';

  if (['b', 'p', 'm'].includes(c)) {
    key = 'bilabial';
    title = 'Âm hai môi (b, p, m): Hai môi khép dính dẹp';
  } else if (c === 'f') {
    key = 'labiodental';
    title = 'Âm răng môi (f): Răng cửa trên chạm môi dưới';
  } else if (['d', 't', 'n', 'l'].includes(c)) {
    key = 'alveolar';
    title = 'Âm đầu lưỡi giữa (d, t, n, l): Đầu lưỡi chạm chân răng trên';
  } else if (['g', 'k', 'h'].includes(c)) {
    key = 'velar';
    title = 'Âm cuống lưỡi (g, k, h): Gốc lưỡi nâng chạm vòm ngạc mềm';
  } else if (['j', 'q', 'x'].includes(c)) {
    key = 'palatal';
    title = 'Âm mặt lưỡi (j, q, x): Mặt lưỡi áp phẳng vòm ngạc cứng';
  } else if (['z', 'c', 's'].includes(c)) {
    key = 'dental';
    title = 'Âm đầu lưỡi trước (z, c, s): Lưỡi duỗi thẳng áp sau răng trên';
  } else if (['zh', 'ch', 'sh', 'r'].includes(c)) {
    key = 'retroflex';
    title = 'Âm cong lưỡi (zh, ch, sh, r): Đầu lưỡi uốn cong vút lên vòm ngạc cứng';
  }

  const imgSrc = MOUTH_IMAGES[key] || MOUTH_IMAGES.bilabial;

  return `
    <div style="display:flex; flex-direction:column; align-items:center; justify-content:center; padding:4px;">
      <img src="${imgSrc}" alt="${title}" style="width:100%; max-height:135px; border-radius:12px; object-fit:cover; box-shadow:0 6px 18px rgba(0,0,0,0.6); border:2px solid rgba(56,189,248,0.4);" />
      <span style="font-size:0.75rem; color:#38bdf8; font-weight:800; margin-top:6px; text-align:center;">${title}</span>
    </div>
  `;
}
